// swift-tools-version: 5.9
// The swift-tools-version declares the minimum version of Swift required to build this package.

import Foundation
import PackageDescription

// Reviewed local binary only. Run scripts/prepare-libbox.py apple first.
for name in ["go.mod", "go.sum", "source.json"] {
    let root = URL(fileURLWithPath: Context.packageDirectory).resolvingSymlinksInPath()
    let pin = try Data(contentsOf: root.appendingPathComponent("../../../../native/" + name))
    let built = try Data(contentsOf: root.appendingPathComponent("Frameworks/Libbox.xcframework/Reviewed." + name))
    precondition(pin == built, "Native dependency pins changed; rerun scripts/prepare-libbox.py apple")
}
let libboxTarget: Target = .binaryTarget(name: "Libbox", path: "Frameworks/Libbox.xcframework")

// Go's runtime in libbox needs libresolv.
let libboxLinkerSettings: [LinkerSetting] = [
    .linkedLibrary("resolv"),
]

let package = Package(
    name: "sing_box",
    platforms: [
        .iOS("15.0"),
    ],
    products: [
        // The Flutter plugin (linked into the app by Flutter's generated package).
        .library(name: "sing-box", targets: ["sing_box"]),
        // The Packet Tunnel provider for the host app's Network Extension target.
        // It has no Flutter dependency.
        .library(name: "SingBoxTunnel", targets: ["SingBoxTunnel"]),
    ],
    dependencies: [
        // Generated by Flutter next to this package in
        // ios/Flutter/ephemeral/Packages/.packages/.
        .package(name: "FlutterFramework", path: "../FlutterFramework"),
    ],
    targets: [
        libboxTarget,
        // Code shared by the app (plugin) and the extension: app group
        // resolution, file locations, keys, libbox helpers.
        .target(
            name: "SingBoxShared",
            dependencies: ["Libbox"],
            linkerSettings: libboxLinkerSettings
        ),
        .target(
            name: "SingBoxTunnel",
            dependencies: ["SingBoxShared", "Libbox"],
            resources: [
                .process("PrivacyInfo.xcprivacy"),
            ],
            linkerSettings: libboxLinkerSettings
        ),
        .target(
            name: "sing_box",
            dependencies: [
                .product(name: "FlutterFramework", package: "FlutterFramework"),
                "SingBoxShared",
                "Libbox",
            ],
            resources: [
                .process("PrivacyInfo.xcprivacy"),
            ],
            linkerSettings: libboxLinkerSettings
        ),
    ]
)
